// === Tab: mySketch ===
function setup() {
	createCanvas(windowWidth, windowHeight);
	rectMode(CENTER);
	noStroke();
}

function draw() {
	background(245, 240, 230);
	const S = min(width, height) / 5;
	translate(width / 2, height / 2);

	let tVal = frameCount * 0.03;
	if (typeof customTime !== 'undefined') tVal = customTime * 2.0;

	const num = 2;
	for (let y = -num; y <= num; y++) {
		for (let x = -num; x <= num; x++) {
			let n = noise(x * 0.5, y * 0.5, tVal);
			let tpe = floor(n * 4);
			push();
			translate(x * S, y * S);
			rotate(n * TWO_PI + tVal * 0.5);

			if (tpe === 0) {
				fill(235, 94, 40);
				circle(0, 0, S * 0.73);
			} else if (tpe === 1) {
				fill(64, 61, 57);
				rect(0, 0, S * 0.6, S * 0.15);
			} else if (tpe === 2) {
				fill(180, 50, 50);
				rect(0, 0, S * 0.5, S * 0.5);
			} else {
				fill(37, 36, 34);
				circle(0, 0, S * 0.4);
			}
			pop();
		}
	}
}
